<script>let {nombre='',activo=true,editar=()=>{},desactivar=()=>{},bloqueado=false,puedeEditar=true}=$props();</script>
<div class="linea"><div><strong>{nombre||'Registro'}</strong><span>{activo?'Activo':'Inactivo'}</span></div><div class="acciones">{#if puedeEditar}<button onclick={editar} disabled={bloqueado||!activo}>Editar</button>{/if}{#if activo}<button class="rojo" onclick={desactivar} disabled={bloqueado}>Desactivar</button>{/if}</div></div>
<style>.linea{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:13px 0;border-bottom:1px solid #e2e8f0}.linea>div:first-child{display:flex;flex-direction:column;gap:6px;min-width:0}.linea strong{overflow-wrap:anywhere}.linea span{color:#64748b;font-size:12px}.acciones{display:flex;gap:8px}button{padding:9px 12px;background:#1e3a8a;color:white;border:0;border-radius:8px;cursor:pointer}.rojo{background:#b91c1c}button:disabled{opacity:.5}@media(max-width:600px){.linea{align-items:stretch;flex-direction:column}.acciones{flex-wrap:wrap}}</style>
